def build_query(template, filters):
    """Build SQL query from template and user-provided filters."""
    query = template

    for key, value in filters.items():
        placeholder = f'${{{key}}}'
        # Direct string substitution of filter values
        if isinstance(value, str):
            query = query.replace(placeholder, f"'{value}'")
        else:
            query = query.replace(placeholder, str(value))

    return query

# Example usage
template = "SELECT * FROM users WHERE email = ${email} AND status = ${status}"
user_filters = {
    "email": "test@example.com' OR '1'='1",
    "status": "active"
}

final_query = build_query(template, user_filters)
print(final_query)
# Executes: SELECT * FROM users WHERE email = 'test@example.com' OR '1'='1' AND status = 'active'
